package com.vibeguard.samples.catalog;
import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
/** Exposes a small public read-only product catalogue. */ @RestController @RequestMapping("/api/products") public class ProductController { private final List<Product> products=List.of(new Product(1,"A5 Notebook","stationery",500),new Product(2,"Ballpoint Pen","stationery",120),new Product(3,"Travel Mug","accessories",1800)); @GetMapping public List<Product> list(@RequestParam(required=false) String category){return products.stream().filter(product->category==null||product.category().equalsIgnoreCase(category)).toList();} @GetMapping("/{id}") public ResponseEntity<Product> get(@PathVariable long id){return products.stream().filter(product->product.id()==id).findFirst().map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());} record Product(long id,String name,String category,long price){} }
